// ── Graph represented as adjacency list ───────────────────────
class Graph {
  constructor(directed = false) {
    this.adj = new Map(); // vertex → [neighbours]
    this.directed = directed;
  }
  addVertex(v) {
    if (!this.adj.has(v)) this.adj.set(v, []);
  }
  addEdge(u, v) {
    this.addVertex(u); this.addVertex(v);
    this.adj.get(u).push(v);
    if (!this.directed) this.adj.get(v).push(u);
  }
  degree(v) { return this.adj.get(v)?.length ?? 0; }
}

const g = new Graph();
[['A','B'],['A','C'],['B','C'],['B','D'],['C','E'],['D','E']].forEach(
  ([u,v]) => g.addEdge(u, v)
);

// Handshaking lemma: sum of degrees = 2|E|
const sumDegrees = [...g.adj.keys()].reduce((s, v) => s + g.degree(v), 0);
const edgeCount = 6;
console.log('Sum of degrees:', sumDegrees, '= 2 ×', edgeCount); // 12 = 2×6

// ── BFS: connectivity and shortest path (unweighted) ──────────
function bfs(graph, start) {
  const visited = new Map(); // vertex → distance from start
  const queue = [start];
  visited.set(start, 0);
  while (queue.length) {
    const u = queue.shift();
    for (const v of graph.adj.get(u) || []) {
      if (!visited.has(v)) {
        visited.set(v, visited.get(u) + 1);
        queue.push(v);
      }
    }
  }
  return visited;
}

const distances = bfs(g, 'A');
console.log('BFS distances from A:');
for (const [v, d] of distances) console.log(' ', v, '→ distance', d);
// A→0, B→1, C→1, D→2, E→2

// ── Euler circuit check ───────────────────────────────────────
function hasEulerCircuit(graph) {
  // All vertices must have even degree
  const oddDegree = [...graph.adj.keys()].filter(v => graph.degree(v) % 2 !== 0);
  return oddDegree.length === 0;
}
console.log('Has Euler circuit:', hasEulerCircuit(g)); // false (B,D,C,E have odd degree?)
// Check: A=2(even), B=3(odd), C=3(odd), D=2(even), E=2(even) → 2 odd → Euler PATH, not circuit

// ── Tree properties ───────────────────────────────────────────
// A tree on n vertices has exactly n-1 edges
// Removing any edge disconnects it; adding any edge creates a cycle

function isTree(adjMap) {
  const vertices = [...adjMap.keys()];
  const n = vertices.length;
  // Count edges (each undirected edge counted twice in adjacency list)
  const edgeCount = vertices.reduce((s, v) => s + adjMap.get(v).length, 0) / 2;
  if (edgeCount !== n - 1) return false;
  // Check connectivity via BFS
  const visited = new Set();
  const queue = [vertices[0]];
  visited.add(vertices[0]);
  while (queue.length) {
    const u = queue.shift();
    for (const v of adjMap.get(u)) {
      if (!visited.has(v)) { visited.add(v); queue.push(v); }
    }
  }
  return visited.size === n;
}

const treeAdj = new Map([
  ['A', ['B','C']],
  ['B', ['A','D','E']],
  ['C', ['A']],
  ['D', ['B']],
  ['E', ['B']]
]);
console.log('Is tree:', isTree(treeAdj)); // true: 5 vertices, 4 edges, connected

// ── Bipartite check (2-coloring via BFS) ──────────────────────
function isBipartite(adjMap) {
  const colour = new Map();
  for (const start of adjMap.keys()) {
    if (colour.has(start)) continue;
    colour.set(start, 0);
    const queue = [start];
    while (queue.length) {
      const u = queue.shift();
      for (const v of adjMap.get(u)) {
        if (!colour.has(v)) {
          colour.set(v, 1 - colour.get(u)); // flip colour
          queue.push(v);
        } else if (colour.get(v) === colour.get(u)) {
          return false; // odd cycle — not bipartite
        }
      }
    }
  }
  return true;
}
console.log('Tree is bipartite:', isBipartite(treeAdj)); // true — all trees are bipartite
